/** Latin words (≥2 chars) + CJK bigrams. Dependency-free and explainable. */
export function tokenize(text        )           {
  const lower = text.toLowerCase()
  const out           = []
  for (const match of lower.matchAll(/[a-z0-9][a-z0-9_-]{1,}/gu)) out.push(match[0])
  const runs = lower.match(/[\u4e00-\u9fff]+/gu) ?? []
  for (const run of runs) {
    if (run.length === 1) out.push(run)
    for (let index = 0; index + 2 <= run.length; index += 1) out.push(run.slice(index, index + 2))
  }
  return [...new Set(out)]
}

/**
 * Clip a display title at punctuation, never mid-clause.
 *
 * Measured live: a negative title rendered as `…即使没有任何外部改动，` — a hard
 * 60-char slice landed on a comma, so the hint read like a damaged sentence.
 */
export function clipTitle(text        , max = 60)         {
  const clean = text.replace(/\s+/gu, ' ').trim()
  if (clean.length <= max) return clean
  const window = clean.slice(0, max)
  // Prefer a sentence end; a comma is only a fallback and must not be KEPT —
  // `改动，…` still reads as a broken clause.
  const sentence = Math.max(...['。', '；', '！', '？'].map((mark) => window.lastIndexOf(mark)))
  if (sentence >= 20) return `${window.slice(0, sentence + 1)}…`
  const comma = Math.max(...['，', '、', '：'].map((mark) => window.lastIndexOf(mark)))
  if (comma >= 20) return `${window.slice(0, comma)}…`
  return `${window}…`
}

export function ageDaysOf(iso                    , now        )         {
  if (iso === undefined) return 30
  const parsed = Date.parse(iso.length <= 10 ? `${iso}T00:00:00Z` : iso)
  if (!Number.isFinite(parsed)) return 30
  return Math.max(0, (now - parsed) / 86_400_000)
}

/** Frontmatter trigger: `when_to_use` (v0.2.0) or legacy `when`. */
export function triggerOf(text        )         {
  return text.match(/^when_to_use:\s*(.+)$/mu)?.[1] ?? text.match(/^when:\s*(.+)$/mu)?.[1] ?? ''
}

/**
 * v0.20: does this text LOOK like an incident log rather than a method?
 *
 * Deliberately a shape test, not a topic test: an incident log narrates a specific
 * failure that happened once ("报错", "traceback", "when … failed", a `xxxError:`
 * line, a stack frame), while a method states how to do something.
 */
export const INCIDENT_MARKERS                    = [
  /(报错|抛错|崩溃|异常栈|堆栈|复现|临时修复|热修|踩坑|翻车|故障)/u,
  /(traceback|stack trace|exception|assertionerror|typeerror|referenceerror|segmentation fault)/iu,
  /\b(panic|crash(ed)?|regression|hotfix|workaround|root cause)\b/iu,
  /\b[A-Z][A-Za-z]*Error\b/u,
  /^\s*at\s+\S+\s+\(/mu,
  /(failed with|fails with|error code|exit code|stderr)/iu,
]

/**
 * v0.15: the trust tier of a stored JSONL record.
 *
 * Absent means a record written before the tier existed. Reading that as
 * `inferred` is the conservative direction: it earns the "请核实" marker and it
 * can never outrank a human statement in a conflict.
 */
export function provenanceOf(value         )                   {
  const text = typeof value === 'string' ? value.trim().toLowerCase() : ''
  return text === 'human' || text === 'tool' ? (text                    ) : 'inferred'
}

/**
 * v0.21 P1 — NEGATIVE-KNOWLEDGE STALENESS, so an old scare cannot veto new work.
 *
 * THE FAILURE MODE
 *
 * A negative path is a rule of the form "this went wrong once, do not do it". It is
 * the most over-powering memory shape in the store: it arrives in the hint as an
 * imperative warning, and a model that has just been told "this翻车" tends to route
 * around a perfectly good approach.
 *
 * A negative from three months ago about a codebase that has since been rewritten is
 * usually not a rule any more — it is an ANECDOTE. Measured shape: a `neg-` about a
 * pytest fixture that no longer exists was still vetoing test-writing advice because
 * nothing decays a negative's authority.
 *
 * THE RULE
 *
 * A negative older than `NEGATIVE_STALE_DAYS` that has never been hit again is
 * DOWN-WEIGHTED (its importance halves) and the hint says so, in brackets, before the
 * claim rather than after it: `[历史偶发错误，仅供参考]`. It is not deleted and not
 * suppressed — an operator can still see it, and a real recurrence re-raises it
 * because the counter of hits is what re-earns the weight.
 *
 * Deliberately requires BOTH conditions: old AND never re-hit. An old negative that
 * keeps recurring is a real rule with a long history, and demoting it would be worse
 * than useless.
 */
export const NEGATIVE_STALE_DAYS = 30

/** What an old, never-rehit negative keeps of its weight. */
export const NEGATIVE_STALE_WEIGHT = 0.5

export function isStaleNegative(
  negative                                                                                      ,
  now = Date.now(),
)          {
  const age = Number(negative.ageDays ?? 0)
  if (!Number.isFinite(age) || age <= NEGATIVE_STALE_DAYS) return false
  // A negative that has been RE-HIT is a live rule, however old its first sighting.
  const hits = Number(negative.hits ?? 1)
  if (Number.isFinite(hits) && hits > 1) return false
  // Counter-evidence already lowers `confidence`; staleness is a different axis.
  void now
  return true
}

